import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Before"]
vws = vals["Before"]

DATE_FORMATS = (
    "%Y-%m-%d %H:%M:%S",
    "%Y-%m-%d %H:%M",
    "%Y-%m-%d",
    "%m/%d/%Y %H:%M:%S",
    "%m/%d/%Y %H:%M",
    "%m/%d/%Y",
    "%m-%d-%Y",
    "%d-%m-%Y",
    "%Y/%m/%d",
)

def parse_date_string(s):
    s = s.strip()
    if not s:
        return None
    try:
        return datetime.fromisoformat(s)
    except ValueError:
        pass
    for fmt in DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    return None

def normalize_value(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        parsed = parse_date_string(s)
        if parsed is not None:
            return parsed
        return s
    return v

def is_date_present(v):
    if v is None:
        return False
    if isinstance(v, bool):
        return False
    if isinstance(v, (datetime, date)):
        return True
    if isinstance(v, (int, float)):
        return True
    if isinstance(v, str):
        return parse_date_string(v) is not None
    return False

# Answer region: Before!K2:K19
for r in range(2, 20):
    g_val = vws.cell(row=r, column=7).value   # Column G
    k_val = vws.cell(row=r, column=11).value  # Column K

    if is_date_present(g_val):
        out_val = normalize_value(g_val)
    else:
        out_val = normalize_value(k_val)

    cell = ws.cell(row=r, column=11)
    cell.value = out_val
    if isinstance(out_val, datetime):
        cell.number_format = "yyyy-mm-dd hh:mm:ss"

    print(r, repr(out_val))

wb.save(OUT)
